'use client';

import { NavigationBarGlass } from './components/ui/navigation-bar-glass';
import { useState } from 'react';
export default function Example() {
  const [page, setPage] = useState('home');
  const items = [{ value: 'home', label: '홈' }, { value: 'search', label: '검색' }, { value: 'profile', label: '내 정보' }].map(item => ({ ...item, outlinedIcon: <span aria-hidden="true">○</span>, filledIcon: <span aria-hidden="true">●</span> }));
  return <><NavigationBarGlass aria-label="주요 화면" items={items} value={page} onValueChange={setPage} /><output>{page}</output></>;
}
